52: 
53:     match &*lock {
54:         Some(dataset) => {
55:             let mut min_lat = 90.0f64;
56:             let mut max_lat = -90.0f64;
57:             let mut min_lon = 180.0f64;
58:             let mut max_lon = -180.0f64;
59:             let mut min_alt = f64::INFINITY;
60:             let mut max_alt = f64::NEG_INFINITY;
61:             let mut valid_coords = 0usize;
62: 
63:             for pt in &dataset.points {
64:                 if pt.latitude != 0.0 || pt.longitude != 0.0 {
65:                     valid_coords += 1;
66:                     min_lat = min_lat.min(pt.latitude);
67:                     max_lat = max_lat.max(pt.latitude);
68:                     min_lon = min_lon.min(pt.longitude);
69:                     max_lon = max_lon.max(pt.longitude);
70:                     min_alt = min_alt.min(pt.altitude_msl);
71:                     max_alt = max_alt.max(pt.altitude_msl);
72:                 }
73:             }
